DROP VIEW IF EXISTS `vv`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vv` AS select sql_no_cache `hawker`.`name` AS `name`,`publication`.`Public_name` AS `public_name`,count(0) AS `count(*)`,`discontinue20192020`.`Publica_id` AS `publica_id` from ((`discontinue20192020` join `hawker` on((`discontinue20192020`.`Hawker_id` = `hawker`.`Hawker_id`))) join `publication` on((`publication`.`Publica_id` = `discontinue20192020`.`Publica_id`))) where ((curdate() between `discontinue20192020`.`Temp_From` and `discontinue20192020`.`Temp_To`) and (`publication`.`TypeP` = _latin1'newspaper')) group by `discontinue20192020`.`Publica_id`;


--
-- Function `test`.`first_mobile`
--

DROP FUNCTION IF EXISTS `first_mobile`;
DELIMITER $$

CREATE DEFINER=`root`@`localhost` FUNCTION `first_mobile`(s TEXT CHARSET latin1) RETURNS varchar(10)
    DETERMINISTIC
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE n INT;
    DECLARE run INT DEFAULT 0;
    DECLARE ch CHAR(1) CHARSET latin1;
    DECLARE num VARCHAR(20) CHARSET latin1;
    IF s IS NULL THEN RETURN NULL; END IF;
    SET n = CHAR_LENGTH(s);
    WHILE i <= n + 1 DO
        IF i <= n THEN SET ch = SUBSTRING(s, i, 1); ELSE SET ch = ' '; END IF;
        IF ch >= '0' AND ch <= '9' THEN
            SET run = run + 1;
        ELSE
            IF run BETWEEN 10 AND 12 THEN
                SET num = SUBSTRING(s, i - run, run);
                IF run = 10 AND LEFT(num,1) IN ('6','7','8','9') THEN
                    RETURN num;
                END IF;
                IF run = 11 AND LEFT(num,1) = '0' AND SUBSTRING(num,2,1) IN ('6','7','8','9') THEN
                    RETURN RIGHT(num,10);
                END IF;
                IF run = 12 AND LEFT(num,2) = '91' AND SUBSTRING(num,3,1) IN ('6','7','8','9') THEN
                    RETURN RIGHT(num,10);
                END IF;
            END IF;
            SET run = 0;
        END IF;
        SET i = i + 1;
    END WHILE;
    RETURN NULL;
END $$

DELIMITER ;
